  tap('bMute', U.toggleMute); ['tGhost', 'bGhost', 'pGhost'].forEach(i => tap(i, U.toggleGhost)); ['tView', 'bView', 'pView'].forEach(i => tap(i, U.toggleView)); tap('tMute', U.toggleMute);
